1	package main
2	
3	import "fmt"
4	
5	// 周期保养规则核心：建立、完成、撤销与方案调整的业务判定及状态推进。
6	//
7	// 日常操作（plan/maintain/unmaintain/adjust）、台账加载校验、保存前校验与
8	// 导入后校验共用本核心，不再各路径分别维护重复规则；命令与持久化层只按
9	// 场景包装核心返回的规则错误（errConflict 或“履历矛盾”）。
10	//
11	// 核心按全库履历序号逐步采纳履历：每一步都以当时的方案段方案、有效完成
12	// 集合与停用状态做判定，绝不用最终状态代替历史状态。核心只推进自己的
13	// 派生状态，从不修改传入的履历、计划或资产等业务记录，也不借校验补字段
14	// 或修复数据；判定失败时派生状态保持判定前原样。
15	
16	// maintRuleCode 为保养规则冲突的类别，供各场景包装成各自的错误信息。
17	type maintRuleCode int
18	
19	const (
20		ruleDuplicateCreate  maintRuleCode = iota // 同一资产多条建立履历
21		ruleBeforeCreate                          // 保养履历出现在建立履历之前
22		ruleAdjustScheme                          // 调整记录的原方案与当时方案不符
23		ruleAdjustNextDue                         // 调整记录的原下一到期日与当时不符
24		ruleAdjustFirstDue                        // 新首次到期日未严格晚于未撤销完成的完成日
25		ruleRevokeOldSegment                      // 撤销目标属于调整前的旧方案段
26		ruleRevokeUnknown                         // 撤销目标不是该资产先前的完成履历
27		ruleRevokeDuplicate                       // 完成被重复撤销
28		ruleRevokeNotLatest                       // 撤销目标不是当时最新的有效完成
29		ruleDoneDeactivated                       // 停用期间登记保养完成
30		ruleDueMismatch                           // 完成周期到期日与当时下一到期日不接续
31		ruleDoneBeforeDue                         // 实际完成日早于周期到期日
32		ruleNextOverflow                          // 推算的下一到期日超出 9999-12-31
33	)
34	
35	// maintRuleError 为核心判定返回的规则冲突，携带各场景包装错误所需的上下文。
36	type maintRuleError struct {
37		code    maintRuleCode
38		assetID string
39		seq     int    // 触发判定的履历序号
40		kind    string // 触发履历类型（ruleBeforeCreate）
41		target  int    // 撤销目标完成履历序号
42		latest  int    // 当时最新有效完成履历序号（ruleRevokeNotLatest）
43		doneSeq int    // 相关完成履历序号（ruleAdjustFirstDue）
44		dateA   string // 相关日期：填写到期日/完成日/新首次到期日/记录的原下一到期日
45		dateB   string // 对照日期：当时下一到期日/周期到期日/完成日
46	}
47	
48	func (e *maintRuleError) Error() string {
49		return fmt.Sprintf("保养规则冲突 %d（资产 %s，履历序号 %d）", int(e.code), e.assetID, e.seq)
50	}
51	
52	// isPlanEvent 报告履历类型是否为保养履历（建立/完成/撤销/调整）。
53	func isPlanEvent(kind string) bool {
54		switch kind {
55		case eventPlanCreate, eventPlanDone, eventPlanRevoke, eventPlanAdjust:
56			return true
57		}
58		return false
59	}
60	
61	// assetMaint 为单资产保养履历链的派生状态：当前方案段方案、由履历推出的
62	// 下一到期日、当前段完成链与撤销集合。段边界按建立与调整履历的全库序号
63	// 划分，不按日期或数组位置。
64	type assetMaint struct {
65		created  bool           // 是否已有建立履历
66		content  string         // 当前方案段的保养内容
67		firstDue string         // 当前方案段的首次到期日
68		interval int            // 当前方案段的间隔天数
69		nextDue  string         // 由履历链推出的下一到期日
70		segDones []int          // 当前段完成履历序号（按序号递增追加）
71		doneDue  map[int]string // 当前段完成序号 -> 周期到期日
72		allDone  map[int]bool   // 全部完成序号（含旧段，用于识别旧段撤销）
73		validDay map[int]int64  // 未撤销完成序号 -> 实际完成日（跨全部方案段）
74		revoked  map[int]bool   // 已撤销完成序号
75	}
76	
77	func newAssetMaint() *assetMaint {
78		return &assetMaint{
79			doneDue:  map[int]string{},
80			allDone:  map[int]bool{},
81			validDay: map[int]int64{},
82			revoked:  map[int]bool{},
83		}
84	}
85	
86	// maintCore 为全部资产的保养派生状态与停用状态的重放器。
87	type maintCore struct {
88		assets      map[string]*assetMaint
89		deactivated map[string]bool
90	}
91	
92	func newMaintCore() *maintCore {
93		return &maintCore{assets: map[string]*assetMaint{}, deactivated: map[string]bool{}}
94	}
95	
96	// state 返回资产的派生状态；尚无保养履历的资产返回空状态。
97	func (c *maintCore) state(assetID string) *assetMaint {
98		st := c.assets[assetID]
99		if st == nil {
100			st = newAssetMaint()
101			c.assets[assetID] = st
102		}
103		return st
104	}
105	
106	// deactivated 报告资产当前是否处于停用状态（由停用/恢复使用履历链推出；
107	// 与保存的资产状态一致，由整库一致性校验保证）。
108	func (c *maintCore) deactivatedNow(assetID string) bool {
109		return c.deactivated[assetID]
110	}
111	
112	// derived 返回资产由履历链推出的当前段方案与下一到期日；
113	// created 报告是否已有建立履历。
114	func (c *maintCore) derived(assetID string) (content, firstDue string, interval int, nextDue string, created bool) {
115		st := c.state(assetID)
116		return st.content, st.firstDue, st.interval, st.nextDue, st.created
117	}
118	
119	// apply 按全库履历序号顺序采纳一条履历：保养履历按当时状态判定并推进派生
120	// 状态，停用/恢复使用履历更新停用状态，其余履历忽略。判定失败返回
121	// *maintRuleError，派生状态保持判定前原样。传入的履历不被修改。
122	func (c *maintCore) apply(e Event) error {
123		switch e.Kind {
124		case eventDeactivate:
125			c.deactivated[e.AssetID] = true
126			return nil
127		case eventReactivate:
128			delete(c.deactivated, e.AssetID)
129			return nil
130		}
131		if !isPlanEvent(e.Kind) {
132			return nil
133		}
134		st := c.state(e.AssetID)
135		switch e.Kind {
136		case eventPlanCreate:
137			return st.applyCreate(e)
138		case eventPlanDone:
139			return st.applyDone(e, c.deactivated[e.AssetID])
140		case eventPlanRevoke:
141			return st.applyRevoke(e)
142		default: // eventPlanAdjust
143			return st.applyAdjust(e)
144		}
145	}
146	
147	// applyCreate 判定并采纳建立履历：每项资产恰一条，开启首个方案段，
148	// 下一到期日即首次到期日。
149	func (m *assetMaint) applyCreate(e Event) error {
150		if m.created {
151			return &maintRuleError{code: ruleDuplicateCreate, assetID: e.AssetID, seq: e.Seq}
152		}
153		m.created = true
154		m.content, m.firstDue, m.interval = e.Content, e.Due, e.Interval
155		m.nextDue = e.Due
156		return nil
157	}
158	
159	// applyDone 判定并采纳完成履历：须在建立之后、非停用期间，周期到期日接续
160	// 当时下一到期日，实际完成日不早于周期到期日；按本段首次日加整数倍间隔
161	// 推进到严格晚于完成日的最早日期，延期跨过的周期不补记录，越界整次拒绝。
162	func (m *assetMaint) applyDone(e Event, deactivated bool) error {
163		if !m.created {
164			return &maintRuleError{code: ruleBeforeCreate, assetID: e.AssetID, seq: e.Seq, kind: e.Kind}
165		}
166		if deactivated {
167			return &maintRuleError{code: ruleDoneDeactivated, assetID: e.AssetID, seq: e.Seq}
168		}
169		if e.Due != m.nextDue {
170			return &maintRuleError{code: ruleDueMismatch, assetID: e.AssetID, seq: e.Seq, dateA: e.Due, dateB: m.nextDue}
171		}
172		dueN, _ := parseDate(e.Due)
173		doneN, _ := parseDate(e.Done)
174		if doneN < dueN {
175			return &maintRuleError{code: ruleDoneBeforeDue, assetID: e.AssetID, seq: e.Seq, dateA: e.Done, dateB: e.Due}
176		}
177		first, _ := parseDate(m.firstDue)
178		next, ok := nextDueAfter(first, int64(m.interval), doneN)
179		if !ok {
180			return &maintRuleError{code: ruleNextOverflow, assetID: e.AssetID, seq: e.Seq, dateA: e.Done}
181		}
182		m.nextDue = formatDate(next)
183		m.segDones = append(m.segDones, e.Seq)
184		m.doneDue[e.Seq] = e.Due
185		m.allDone[e.Seq] = true
186		m.validDay[e.Seq] = doneN
187		return nil
188	}
189	
190	// applyRevoke 判定并采纳撤销履历：目标须为当前方案段内先前的完成履历、
191	// 未撤销且为当时最新有效；撤销后下一到期日恢复为该完成的周期到期日，
192	// 其完成日不再限制后续调整。旧段完成不能再撤销。
193	func (m *assetMaint) applyRevoke(e Event) error {
194		if !m.created {
195			return &maintRuleError{code: ruleBeforeCreate, assetID: e.AssetID, seq: e.Seq, kind: e.Kind}
196		}
197		due, ok := m.doneDue[e.TargetSeq]
198		if !ok {
199			if m.allDone[e.TargetSeq] {
200				return &maintRuleError{code: ruleRevokeOldSegment, assetID: e.AssetID, seq: e.Seq, target: e.TargetSeq}
201			}
202			return &maintRuleError{code: ruleRevokeUnknown, assetID: e.AssetID, seq: e.Seq, target: e.TargetSeq}
203		}
204		if m.revoked[e.TargetSeq] {
205			return &maintRuleError{code: ruleRevokeDuplicate, assetID: e.AssetID, seq: e.Seq, target: e.TargetSeq}
206		}
207		latest := 0
208		for _, seq := range m.segDones {
209			if !m.revoked[seq] {
210				latest = seq
211			}
212		}
213		if latest != e.TargetSeq {
214			return &maintRuleError{code: ruleRevokeNotLatest, assetID: e.AssetID, seq: e.Seq, target: e.TargetSeq, latest: latest}
215		}
216		m.revoked[e.TargetSeq] = true
217		delete(m.validDay, e.TargetSeq)
218		m.nextDue = due
219		return nil
220	}
221	
222	// applyAdjust 判定并采纳调整履历：记录的原方案与原下一到期日须与当时状态
223	// 一致，新首次到期日须严格晚于当时所有未撤销完成（跨全部方案段）的实际
224	// 完成日。采纳后开启新方案段：采用新方案，下一到期日设为新首次到期日，
225	// 不补任何完成记录，旧段完成不能再撤销。
226	func (m *assetMaint) applyAdjust(e Event) error {
227		if !m.created {
228			return &maintRuleError{code: ruleBeforeCreate, assetID: e.AssetID, seq: e.Seq, kind: e.Kind}
229		}
230		if e.OldContent != m.content || e.OldDue != m.firstDue || e.OldInterval != m.interval {
231			return &maintRuleError{code: ruleAdjustScheme, assetID: e.AssetID, seq: e.Seq}
232		}
233		if e.OldNextDue != m.nextDue {
234			return &maintRuleError{code: ruleAdjustNextDue, assetID: e.AssetID, seq: e.Seq, dateA: e.OldNextDue, dateB: m.nextDue}
235		}
236		newFirst, _ := parseDate(e.Due)
237		// 未撤销完成的完成日沿段内严格递增（各完成日不早于其周期到期日，而到期日
238		// 严格推进；跨段的新首次日又须晚于当时全部有效完成日），取最大者即判定
239		// 边界，结果与逐一比较等价且确定。
240		maxSeq, maxDay := 0, int64(-1)
241		for seq, day := range m.validDay {
242			if day > maxDay {
243				maxSeq, maxDay = seq, day
244			}
245		}
246		if maxDay >= 0 && newFirst <= maxDay {
247			return &maintRuleError{code: ruleAdjustFirstDue, assetID: e.AssetID, seq: e.Seq, dateA: e.Due, doneSeq: maxSeq, dateB: formatDate(maxDay)}
248		}
249		m.content, m.firstDue, m.interval = e.NewContent, e.Due, e.Interval
250		m.nextDue = e.Due
251		m.segDones = nil
252		m.doneDue = map[int]string{}
253		return nil
254	}
255

