1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"sort"
7	)
8	
9	// 周期保养计划与完成登记。
10	//
11	// 日期一律为 0001 至 9999 年的公历日历日（YYYY-MM-DD），按日历日运算：
12	// 不涉及时区与运行时刻，内部以“距 0001-01-01 的天数”做整数运算，避免
13	// time.Time 的时区、跨度（time.Duration 约 292 年上限）与年份范围问题。
14	//
15	// 每个计划恰有一条建立履历（含初始计划：内容、首次到期日、间隔天数），
16	// 每次完成登记追加一条完成履历（含周期到期日、实际完成日、结果），每次撤销
17	// 误登记追加一条撤销履历（含目标完成履历序号、理由），每次方案调整追加一条
18	// 调整履历（含前后方案、原下一到期日与理由）。建立与调整履历的全库序号把
19	// 保养历史划分为方案段：完成与撤销只作用于当时所在段，下一到期日按本段
20	// 首次日加整数倍间隔推进；计划保存的是当前段方案与由履历链推出的下一到期日，
21	// 加载与保存时核对二者一致。
22	// 建立、完成、撤销与调整的业务判定及状态推进由保养规则核心（maintcore.go）
23	// 统一完成，日常操作、台账加载、保存前校验与导入后校验共用；本文件只做
24	// 记录级前置检查（存在性、参数形式）并按操作场景包装核心的规则错误。
25	// 保养不创建或终结工单、不消耗工单编号，不改变资产状态、请求绑定或停机统计。
26	
27	// Plan 为资产的周期保养计划；每项资产最多一个，不可覆盖，但可经调整履历
28	// 更换内容、周期起点与间隔。Content/FirstDue/IntervalDays 为当前方案段的
29	// 方案，NextDue 为由履历链推出的下一到期日，随每次完成登记推进、随撤销
30	// 回退、随调整重置为新首次到期日。
31	type Plan struct {
32		AssetID      string `json:"asset_id"`
33		Content      string `json:"content"`
34		FirstDue     string `json:"first_due"`
35		IntervalDays int    `json:"interval_days"`
36		NextDue      string `json:"next_due"`
37	}
38	
39	// maxDayNum 为 9999-12-31 的日序号（0001-01-01 为 0）。
40	const maxDayNum = 3652058
41	
42	// daysFromCivil 返回公历日期距 0001-01-01 的天数（该日为 0）。
43	// 输入须为 0001 至 9999 年间的有效日期（由 parseDate 保证）。
44	func daysFromCivil(y, m, d int) int64 {
45		yy := int64(y)
46		if m <= 2 {
47			yy--
48		}
49		era := yy / 400
50		yoe := yy - era*400
51		mp := int64((m + 9) % 12)
52		doy := (153*mp+2)/5 + int64(d) - 1
53		doe := yoe*365 + yoe/4 - yoe/100 + doy
54		return era*146097 + doe - 306
55	}
56	
57	// civilFromDays 为 daysFromCivil 的逆运算。
58	func civilFromDays(n int64) (int, int, int) {
59		z := n + 306
60		era := z / 146097
61		doe := z - era*146097
62		yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
63		y := yoe + era*400
64		doy := doe - (365*yoe + yoe/4 - yoe/100)
65		mp := (5*doy + 2) / 153
66		d := doy - (153*mp+2)/5 + 1
67		if mp < 10 {
68			return int(y), int(mp + 3), int(d)
69		}
70		return int(y + 1), int(mp - 9), int(d)
71	}
72	
73	func isLeapYear(y int) bool {
74		return y%4 == 0 && (y%100 != 0 || y%400 == 0)
75	}
76	
77	func daysInMonth(y, m int) int {
78		switch m {
79		case 1, 3, 5, 7, 8, 10, 12:
80			return 31
81		case 4, 6, 9, 11:
82			return 30
83		}
84		if isLeapYear(y) {
85			return 29
86		}
87		return 28
88	}
89	
90	// atoiN 解析定长十进制数字串；含非数字字符时 ok=false。
91	func atoiN(s string) (int, bool) {
92		n := 0
93		for i := 0; i < len(s); i++ {
94			if s[i] < '0' || s[i] > '9' {
95				return 0, false
96			}
97			n = n*10 + int(s[i]-'0')
98		}
99		return n, true
100	}
101	
102	// parseDate 解析 YYYY-MM-DD 形式的公历日期（0001 至 9999 年，须为零填充的
103	// 完整形式），返回日序号。闰日等按公历规则校验。
104	func parseDate(s string) (int64, error) {
105		if len(s) != 10 || s[4] != '-' || s[7] != '-' {
106			return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
107		}
108		y, ok1 := atoiN(s[0:4])
109		m, ok2 := atoiN(s[5:7])
110		d, ok3 := atoiN(s[8:10])
111		if !ok1 || !ok2 || !ok3 {
112			return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
113		}
114		if y < 1 || m < 1 || m > 12 || d < 1 || d > daysInMonth(y, m) {
115			return 0, fmt.Errorf("不是 0001 至 9999 年间的有效公历日期: %q", s)
116		}
117		return daysFromCivil(y, m, d), nil
118	}
119	
120	// formatDate 把日序号格式化为 YYYY-MM-DD。
121	func formatDate(n int64) string {
122		y, m, d := civilFromDays(n)
123		return fmt.Sprintf("%04d-%02d-%02d", y, m, d)
124	}
125	
126	// nextDueAfter 返回首次到期日加整数倍间隔所得日期中，严格晚于 after 的最早
127	// 日期。结果超出 9999-12-31 时 ok=false。间隔必须为正整数。
128	func nextDueAfter(first, interval, after int64) (int64, bool) {
129		var k int64
130		if after >= first {
131			k = (after-first)/interval + 1
132		}
133		// k ≥ 1 且间隔本身已超出剩余日期范围时，结果必然越界；先判断避免溢出。
134		if k > 0 && interval > maxDayNum-first {
135			return 0, false
136		}
137		n := first + k*interval
138		if n > maxDayNum {
139			return 0, false
140		}
141		return n, true
142	}
143	
144	// findPlan 返回资产的保养计划，无计划时返回 nil。
145	func (s *store) findPlan(assetID string) *Plan {
146		for _, p := range s.data.Plans {
147			if p.AssetID == assetID {
148				return p
149			}
150		}
151		return nil
152	}
153	
154	// appendMaintEvent 以给定序号追加保养履历（建立或完成）。保养履历不属于任何
155	// 工单，from/to 恒为空；due/done/interval 按履历类型使用。
156	func (s *store) appendMaintEvent(seq int, assetID, kind, content, due, done string, interval int) {
157		s.data.Events = append(s.data.Events, Event{
158			Seq:      seq,
159			AssetID:  assetID,
160			Kind:     kind,
161			Content:  content,
162			Due:      due,
163			Done:     done,
164			Interval: interval,
165			Time:     s.now(),
166		})
167	}
168	
169	// maintCore 用当前履历重放保养规则核心，供日常操作做业务判定。数据在加载
170	// 与每次保存前均通过整库一致性检查，重放必然成功；失败说明内存数据损坏。
171	// 核心只推进自己的派生状态，不修改任何业务记录。
172	func (s *store) maintCore() (*maintCore, error) {
173		core := newMaintCore()
174		sorted := make([]Event, len(s.data.Events))
175		copy(sorted, s.data.Events)
176		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
177		for _, e := range sorted {
178			if err := core.apply(e); err != nil {
179				return nil, fmt.Errorf("数据内部错误：保养履历重放失败: %w", err)
180			}
181		}
182		return core, nil
183	}
184	
185	// maintOpError 把核心返回的规则冲突包装为日常操作场景的错误（errConflict
186	// 类别，面向命令行的说明）。合法操作不可能触发的类别视为数据内部错误。
187	func maintOpError(err error) error {
188		var re *maintRuleError
189		if !errors.As(err, &re) {
190			return err
191		}
192		switch re.code {
193		case ruleDoneDeactivated:
194			return fmt.Errorf("%w: 资产 %s 已停用，不能登记保养完成", errConflict, re.assetID)
195		case ruleDueMismatch:
196			return fmt.Errorf(
197				"%w: 周期到期日 %s 与资产 %s 当前下一到期日 %s 不符（旧周期不能重复登记，也不能登记新周期）",
198				errConflict, re.dateA, re.assetID, re.dateB)
199		case ruleDoneBeforeDue:
200			return fmt.Errorf("%w: 实际完成日 %s 早于周期到期日 %s", errConflict, re.dateA, re.dateB)
201		case ruleNextOverflow:
202			return fmt.Errorf(
203				"%w: 按完成日 %s 推算的下一到期日超出 9999-12-31，无法登记本次完成", errConflict, re.dateA)
204		case ruleAdjustFirstDue:
205			return fmt.Errorf(
206				"%w: 新首次到期日 %s 须严格晚于资产 %s 未撤销完成的实际完成日 %s",
207				errConflict, re.dateA, re.assetID, re.dateB)
208		case ruleRevokeOldSegment:
209			return fmt.Errorf(
210				"%w: 完成履历序号 %d 属于资产 %s 调整前的旧方案段，旧段完成不能再撤销",
211				errConflict, re.target, re.assetID)
212		case ruleRevokeDuplicate:
213			return fmt.Errorf("%w: 完成履历序号 %d 已撤销，不能重复撤销", errConflict, re.target)
214		case ruleRevokeNotLatest:
215			return fmt.Errorf(
216				"%w: 完成履历序号 %d 不是资产 %s 当前方案段最新的有效完成（当前为序号 %d），存在更晚有效完成时不能撤销",
217				errConflict, re.target, re.assetID, re.latest)
218		}
219		return fmt.Errorf("数据内部错误：%v", err)
220	}
221	
222	// createPlan 为资产建立唯一的周期保养计划：每项资产最多一个，已有计划时拒绝，
223	// 不覆盖。成功时追加一条含初始计划的建立履历，下一到期日即首次到期日。
224	// 失败路径不修改任何业务数据。
225	func (s *store) createPlan(assetID, content, firstDue string, intervalDays int) (*Plan, error) {
226		if s.findAsset(assetID) == nil {
227			return nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
228		}
229		if s.findPlan(assetID) != nil {
230			return nil, fmt.Errorf("%w: 资产 %s 已有保养计划，不能重复建立或覆盖", errConflict, assetID)
231		}
232		if content == "" {
233			return nil, fmt.Errorf("%w: 保养内容不能为空", errConflict)
234		}
235		if intervalDays < 1 {
236			return nil, fmt.Errorf("%w: 保养间隔天数须为正整数", errConflict)
237		}
238		if _, err := parseDate(firstDue); err != nil {
239			return nil, fmt.Errorf("%w: 首次到期日无效：%s", errConflict, err)
240		}
241		core, err := s.maintCore()
242		if err != nil {
243			return nil, err
244		}
245		// 候选履历不含序号：核心判定不依赖序号，真正的序号在判定通过后分配，
246		// 失败路径不消耗序号。
247		if err := core.apply(Event{
248			AssetID: assetID, Kind: eventPlanCreate, Content: content, Due: firstDue, Interval: intervalDays,
249		}); err != nil {
250			return nil, maintOpError(err)
251		}
252		eventSeq, err := s.nextEventSeq()
253		if err != nil {
254			return nil, err
255		}
256		_, _, _, nextDue, _ := core.derived(assetID)
257		p := &Plan{
258			AssetID:      assetID,
259			Content:      content,
260			FirstDue:     firstDue,
261			IntervalDays: intervalDays,
262			NextDue:      nextDue,
263		}
264		s.data.Plans = append(s.data.Plans, p)
265		s.appendMaintEvent(eventSeq, assetID, eventPlanCreate, content, firstDue, "", intervalDays)
266		return p, nil
267	}
268	
269	// adjustPlan 调整已有计划的保养方案：更换内容、周期起点（新首次到期日）与
270	// 间隔，理由非空；仅已有计划的资产可调整，维修中、停用时也允许。新首次到期日
271	// 须严格晚于该资产所有未撤销完成（含调整前旧段）的实际完成日，没有有效完成
272	// 则无此限制。成功时追加一条记录前后方案、原下一到期日、理由与时间的资产级
273	// 调整履历，以该履历的全库序号开启新方案段：计划采用新方案，下一到期日设为
274	// 新首次到期日，不补任何完成记录，旧段完成不能再撤销。调整不改变资产状态、
275	// 工单、请求绑定或停机统计。失败路径不修改任何业务数据。
276	func (s *store) adjustPlan(assetID, content, firstDue string, intervalDays int, reason string) (*Plan, *Plan, error) {
277		if s.findAsset(assetID) == nil {
278			return nil, nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
279		}
280		p := s.findPlan(assetID)
281		if p == nil {
282			return nil, nil, fmt.Errorf("%w: 资产 %s 没有保养计划，不能调整", errNotFound, assetID)
283		}
284		if content == "" {
285			return nil, nil, fmt.Errorf("%w: 保养内容不能为空", errConflict)
286		}
287		if reason == "" {
288			return nil, nil, fmt.Errorf("%w: 调整理由不能为空", errConflict)
289		}
290		if intervalDays < 1 {
291			return nil, nil, fmt.Errorf("%w: 保养间隔天数须为正整数", errConflict)
292		}
293		if _, err := parseDate(firstDue); err != nil {
294			return nil, nil, fmt.Errorf("%w: 新首次到期日无效：%s", errConflict, err)
295		}
296		core, err := s.maintCore()
297		if err != nil {
298			return nil, nil, err
299		}
300		old := *p
301		// 候选履历记录前后方案与原下一到期日（不含序号，核心判定不依赖序号）；
302		// 原方案接续与新首次日限制由共享核心判定。
303		cand := Event{
304			AssetID: assetID, Kind: eventPlanAdjust, Content: reason,
305			Due: firstDue, Interval: intervalDays, NewContent: content,
306			OldContent: old.Content, OldDue: old.FirstDue, OldInterval: old.IntervalDays, OldNextDue: old.NextDue,
307		}
308		if err := core.apply(cand); err != nil {
309			return nil, nil, maintOpError(err)
310		}
311		eventSeq, err := s.nextEventSeq()
312		if err != nil {
313			return nil, nil, err
314		}
315		cand.Seq = eventSeq
316		cand.Time = s.now()
317		s.data.Events = append(s.data.Events, cand)
318		p.Content = content
319		p.FirstDue = firstDue
320		p.IntervalDays = intervalDays
321		p.NextDue = firstDue
322		return p, &old, nil
323	}
324	
325	// completePlan 登记当前方案段下一周期的保养完成：所填到期日必须等于当前下一
326	// 到期日（旧周期不能重复登记，也不能登记尚未到期的新周期），实际完成日不得早于
327	// 周期到期日。成功时追加一条完成履历，并把下一到期日推进到本段首次到期日加
328	// 整数倍间隔所得日期中严格晚于完成日的最早日期；延期跨过的周期不生成完成记录。
329	// 若下一到期日超出 9999-12-31，整次拒绝。返回完成履历的全库序号。
330	// 失败路径不修改任何业务数据。
331	func (s *store) completePlan(assetID, due, done, result string) (*Plan, string, int, error) {
332		if s.findAsset(assetID) == nil {
333			return nil, "", 0, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
334		}
335		p := s.findPlan(assetID)
336		if p == nil {
337			return nil, "", 0, fmt.Errorf("%w: 资产 %s 没有保养计划", errNotFound, assetID)
338		}
339		core, err := s.maintCore()
340		if err != nil {
341			return nil, "", 0, err
342		}
343		if core.deactivatedNow(assetID) {
344			// 停用期间拒绝保养完成登记；停用不暂停或重算周期，保存的下一到期日不变。
345			return nil, "", 0, fmt.Errorf("%w: 资产 %s 已停用，不能登记保养完成", errConflict, assetID)
346		}
347		if result == "" {
348			return nil, "", 0, fmt.Errorf("%w: 保养结果不能为空", errConflict)
349		}
350		if _, err := parseDate(due); err != nil {
351			return nil, "", 0, fmt.Errorf("%w: 周期到期日无效：%s", errConflict, err)
352		}
353		if _, err := parseDate(done); err != nil {
354			return nil, "", 0, fmt.Errorf("%w: 实际完成日无效：%s", errConflict, err)
355		}
356		// 候选履历不含序号（核心判定不依赖序号）；接续、完成日不早于到期日与
357		// 日期范围判定全部由共享核心完成。
358		cand := Event{AssetID: assetID, Kind: eventPlanDone, Content: result, Due: due, Done: done}
359		if err := core.apply(cand); err != nil {
360			return nil, "", 0, maintOpError(err)
361		}
362		eventSeq, err := s.nextEventSeq()
363		if err != nil {
364			return nil, "", 0, err
365		}
366		_, _, _, next, _ := core.derived(assetID)
367		p.NextDue = next
368		s.appendMaintEvent(eventSeq, assetID, eventPlanDone, result, due, done, 0)
369		return p, next, eventSeq, nil
370	}
371	
372	// revokedDoneSeqs 返回已被撤销的保养完成履历序号集合。
373	func (s *store) revokedDoneSeqs() map[int]bool {
374		revoked := map[int]bool{}
375		for _, e := range s.data.Events {
376			if e.Kind == eventPlanRevoke {
377				revoked[e.TargetSeq] = true
378			}
379		}
380		return revoked
381	}
382	
383	// revokeCompletion 撤销误登记的保养完成：目标须为该资产当前方案段内按序号最新
384	// 的未撤销完成（存在更晚有效完成时拒绝；撤销后可继续撤销本段此前最新有效完成；
385	// 调整前旧段的完成不能再撤销）。成功时保留原完成的日期、结果与时间，追加一条
386	// 含目标序号、理由与操作时间的撤销履历，并把下一到期日恢复为该完成的周期到期日
387	// （延期跨过的周期不补记录）。维修或其他资产事件不阻止撤销。失败路径不修改任何
388	// 业务数据。
389	func (s *store) revokeCompletion(assetID string, targetSeq int, reason string) (*Plan, *Event, error) {
390		if s.findAsset(assetID) == nil {
391			return nil, nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
392		}
393		if reason == "" {
394			return nil, nil, fmt.Errorf("%w: 撤销理由不能为空", errConflict)
395		}
396		p := s.findPlan(assetID)
397		if p == nil {
398			return nil, nil, fmt.Errorf("%w: 资产 %s 没有保养计划", errNotFound, assetID)
399		}
400		var target *Event
401		for i := range s.data.Events {
402			if s.data.Events[i].Seq == targetSeq {
403				target = &s.data.Events[i]
404				break
405			}
406		}
407		if target == nil {
408			return nil, nil, fmt.Errorf("%w: 未知履历序号 %d", errNotFound, targetSeq)
409		}
410		if target.Kind != eventPlanDone || target.AssetID != assetID {
411			return nil, nil, fmt.Errorf("%w: 履历序号 %d 不是资产 %s 的保养完成履历", errConflict, targetSeq, assetID)
412		}
413		core, err := s.maintCore()
414		if err != nil {
415			return nil, nil, err
416		}
417		// 候选履历不含序号（核心判定不依赖序号）；段归属、重复撤销与最新有效
418		// 判定由共享核心完成。
419		cand := Event{AssetID: assetID, Kind: eventPlanRevoke, Content: reason, TargetSeq: targetSeq}
420		if err := core.apply(cand); err != nil {
421			return nil, nil, maintOpError(err)
422		}
423		eventSeq, err := s.nextEventSeq()
424		if err != nil {
425			return nil, nil, err
426		}
427		cand.Seq = eventSeq
428		cand.Time = s.now()
429		s.data.Events = append(s.data.Events, cand)
430		_, _, _, next, _ := core.derived(assetID)
431		p.NextDue = next
432		return p, target, nil
433	}
434	
435	// duePlanRow 为到期查询的一行结果。
436	type duePlanRow struct {
437		AssetID string
438		Name    string
439		Content string
440		Due     string
441	}
442	
443	// duePlans 列出下一到期日不晚于 date 的保养计划，按到期日再按资产编号排序。
444	// 停用资产不参与到期查询：停用不暂停或重算周期，保存的下一到期日保持不变，
445	// 恢复使用后仍按该日期参与查询，逾期计划显示原到期日。
446	// 只读：不写文件、不初始化目录、不推进计划。date 须为有效日期（调用方校验）。
447	func (s *store) duePlans(date string) []duePlanRow {
448		rows := make([]duePlanRow, 0)
449		for _, p := range s.data.Plans {
450			// YYYY-MM-DD 零填充形式的字典序即时间顺序。
451			if p.NextDue > date {
452				continue
453			}
454			a := s.findAsset(p.AssetID)
455			if a == nil {
456				continue // 整库一致性检查已保证归属；防御性跳过
457			}
458			if a.Status == statusDeactivated {
459				continue
460			}
461			rows = append(rows, duePlanRow{AssetID: p.AssetID, Name: a.Name, Content: p.Content, Due: p.NextDue})
462		}
463		sort.Slice(rows, func(i, j int) bool {
464			if rows[i].Due != rows[j].Due {
465				return rows[i].Due < rows[j].Due
466			}
467			return rows[i].AssetID < rows[j].AssetID
468		})
469		return rows
470	}
471

