3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9	)
10	
11	// 本地清单批量报修：从 --file 指定的 JSON 清单一次提交多项设备故障报修，
12	// 整批原子生效。清单文件只读，不会被修改。
13	//
14	// 清单格式：JSON 数组，每项为一个对象，含三个非空字符串字段——
15	// asset_id（资产编号）、description（故障描述）、request_id（报修请求标识）。
16	// 空清单、JSON 格式错误、含未知字段或缺少必填内容均整批拒绝（退出码 2）。
17	//
18	// 请求标识仍仅用于同一数据目录内的报修去重，不引入批次标识：
19	//   - 批内同一请求标识搭配相同资产与描述的重复项合并为一项（按首次出现处理，
20	//     不消耗编号）；同一标识搭配不同资产或描述——无论冲突来自批内还是已有
21	//     绑定——均整批拒绝。
22	//   - 已有相同绑定的项为重放：返回原工单及当前状态，不新增履历；即使原单已
23	//     关闭或取消、资产停用或已有后来工单，重放也不重开原单、不改变资产或
24	//     后来工单。纯重放为只读：不写文件、不初始化目录，编号或履历容量耗尽也
25	//     不妨碍合法重放。
26	//   - 其余项按 report 规则创建工单：未知资产、停用资产、已有未关闭工单（含
27	//     本批前项刚开出的工单）均整批拒绝；旧请求重放与该资产的一项合法新报修
28	//     可以共存。新工单按清单首次出现顺序分配连续工单编号与报修履历序号，
29	//     每张新单恰有一条报修履历，所属资产变为“维修中”，不追加批次业务事件。
30	//
31	// 含新请求时，整批工单、状态、履历与请求绑定一次原子保存后才输出成功结果。
32	// 任一项不合法、容量不足或读写失败均整批失败并指出清单项位置，不输出部分
33	// 成功结果：已有台账与输入清单字节不变，不留下部分记录或请求绑定、不消耗
34	// 编号，恢复条件后可重试。
35	
36	// manifestItem 为报修清单中的一项报修请求。
37	type manifestItem struct {
38		AssetID     string `json:"asset_id"`
39		Description string `json:"description"`
40		RequestID   string `json:"request_id"`
41	}
42	
43	// readBatchManifest 完整读取并校验报修清单。文件读取失败为读写失败（退出码 1）；
44	// 空清单、格式错误、缺少必填内容或含未知字段为清单格式错误（*usageError，退出码 2）。
45	// 清单文件只读，任何结果都不会修改它。
46	func readBatchManifest(path string) ([]manifestItem, error) {
47		raw, err := os.ReadFile(path)
48		if err != nil {
49			return nil, fmt.Errorf("读取报修清单失败: %w", err)
50		}
51		if len(bytes.TrimSpace(raw)) == 0 {
52			return nil, &usageError{msg: fmt.Sprintf(
53				"报修清单 %s 为空：清单须为至少含一项报修的 JSON 数组", path)}
54		}
55		var items []manifestItem
56		dec := json.NewDecoder(bytes.NewReader(raw))
57		dec.DisallowUnknownFields()
58		if err := dec.Decode(&items); err != nil {
59			return nil, &usageError{msg: fmt.Sprintf(
60				"报修清单格式错误: %s（清单须为 JSON 数组，每项含非空的 asset_id、description、request_id）", err)}
61		}
62		var extra json.RawMessage
63		if err := dec.Decode(&extra); err != io.EOF {
64			if err == nil {
65				return nil, &usageError{msg: "报修清单格式错误：JSON 数组之后存在多余内容"}
66			}
67			return nil, &usageError{msg: fmt.Sprintf("报修清单格式错误: %s", err)}
68		}
69		if len(items) == 0 {
70			return nil, &usageError{msg: "报修清单为空：至少须包含一项报修"}
71		}
72		for i, it := range items {
73			pos := i + 1
74			switch {
75			case it.AssetID == "":
76				return nil, &usageError{msg: fmt.Sprintf("清单第 %d 项：资产编号（asset_id）不能为空", pos)}
77			case it.Description == "":
78				return nil, &usageError{msg: fmt.Sprintf("清单第 %d 项：故障描述（description）不能为空", pos)}
79			case it.RequestID == "":
80				return nil, &usageError{msg: fmt.Sprintf("清单第 %d 项：报修请求标识（request_id）不能为空", pos)}
81			}
82		}
83		return items, nil
84	}
85	
86	// batchOutcome 为批量报修中一个唯一请求标识的处理结果，用于输出。
87	type batchOutcome struct {
88		RequestID string
89		AssetID   string
90		TicketID  string
91		Status    string
92		Replayed  bool
93	}
94	
95	// batchReport 按清单顺序处理全部报修项，返回每个唯一请求标识（按首次出现
96	// 顺序）的结果与新增工单数。所有校验与冲突检查任一失败都整批失败：内存中的
97	// 部分变更随台账对象一并丢弃，不保存、不消耗编号、不绑定请求标识。
98	func (s *store) batchReport(items []manifestItem) ([]batchOutcome, int, error) {
99		// 批内去重：同一请求标识首次出现时记录；相同资产与描述的重复项合并为一项，
100		// 搭配不同资产或描述的整批拒绝。
101		type firstSeen struct {
102			pos         int
103			assetID     string
104			description string
105		}
106		seen := map[string]firstSeen{}
107		unique := make([]manifestItem, 0, len(items))
108		positions := make([]int, 0, len(items))
109		for i, it := range items {
110			pos := i + 1
111			if prev, ok := seen[it.RequestID]; ok {
112				if prev.assetID != it.AssetID || prev.description != it.Description {
113					return nil, 0, fmt.Errorf(
114						"清单第 %d 项与第 %d 项的请求标识 %q 相同，但资产编号或故障描述不同，整批拒绝",
115						pos, prev.pos, it.RequestID)
116				}
117				continue // 重复项合并，不消耗编号
118			}
119			seen[it.RequestID] = firstSeen{pos: pos, assetID: it.AssetID, description: it.Description}
120			unique = append(unique, it)
121			positions = append(positions, pos)
122		}
123	
124		outcomes := make([]batchOutcome, 0, len(unique))
125		newCount := 0
126		for i, it := range unique {
127			// 与单项 report 共享同一套规则与请求绑定：已有相同绑定返回原工单
128			// （重放），否则按原报修规则开单；同资产第二张新单会撞上本批前项
129			// 刚开出的未关闭工单而整批拒绝。
130			t, replay, err := s.report(it.AssetID, it.Description, it.RequestID)
131			if err != nil {
132				return nil, 0, fmt.Errorf("清单第 %d 项（请求标识 %q）: %s",
133					positions[i], it.RequestID, friendlyErr(err.Error()))
134			}
135			if !replay {
136				newCount++
137			}
138			outcomes = append(outcomes, batchOutcome{
139				RequestID: it.RequestID,
140				AssetID:   it.AssetID,
141				TicketID:  t.ID,
142				Status:    t.Status,
143				Replayed:  replay,
144			})
145		}
146		return outcomes, newCount, nil
147	}
148	
149	// cmdBatchReport 批量报修命令入口。清单格式错误为退出码 2；业务冲突、容量
150	// 不足与读写失败为退出码 1。含新请求时整批一次原子保存后才输出成功结果；
151	// 纯重放为只读，不写文件、不初始化目录。
152	func cmdBatchReport(args []string, w io.Writer) error {
153		var opts cmdOptions
154		var file string
155		fs := newFlagSet("batch-report", &opts)
156		fs.StringVar(&file, "file", "", "报修清单文件路径（必填；JSON 数组，每项含非空的 asset_id、description、request_id；清单只读）")
157		if err := parseFlags(fs, args); err != nil {
158			return err
159		}
160		if err := requireFlag(fs, file, "file"); err != nil {
161			return err
162		}
163		items, err := readBatchManifest(file)
164		if err != nil {
165			return err
166		}
167		// openStore 已先做整库一致性检查：损坏或关联矛盾按原规则拒绝（退出码 1）。
168		s, err := openStore(opts.dataDir)
169		if err != nil {
170			return err
171		}
172		outcomes, newCount, err := s.batchReport(items)
173		if err != nil {
174			return err
175		}
176		if newCount > 0 {
177			// 整批工单、状态、履历与请求绑定一次原子保存（保存前再次校验整库
178			// 一致性）；失败时原文件字节不变，不留下部分记录，恢复后可重试。
179			if err := s.save(); err != nil {
180				return err
181			}
182		}
183		fmt.Fprintf(w, "批量报修完成：共 %d 项请求（新增 %d 项，重放 %d 项）。\n",
184			len(outcomes), newCount, len(outcomes)-newCount)
185		for _, o := range outcomes {
186			kind := "新增"
187			if o.Replayed {
188				kind = "重放"
189			}
190			fmt.Fprintf(w, "%s\t%s\t%s\t%s\t%s\n", o.RequestID, o.AssetID, o.TicketID, o.Status, kind)
191		}
192		if newCount == 0 {
193			fmt.Fprintln(w, "全部为既有请求的相同重放，未创建工单、未写入任何记录。")
194		}
195		return nil
196	}
