294		raw, err := os.ReadFile(path)
295		if err != nil {
296			if errors.Is(err, os.ErrNotExist) {
297				if allowMissing {
298					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
299				}
300				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
301			}
302			return nil, fmt.Errorf("读取数据文件失败: %w", err)
303		}
304		if len(bytes.TrimSpace(raw)) == 0 {
305			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
306		}
307		var d storeData
308		if err := json.Unmarshal(raw, &d); err != nil {
309			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
310		}
311		if d.EventsJSON != nil {
312			d.Events = make([]Event, len(d.EventsJSON))
313			for i, ej := range d.EventsJSON {
314				ev, err := ej.toEvent()
315				if err != nil {
316					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
317				}
318				d.Events[i] = ev
319			}
320		}
321		// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
322		if d.Plans == nil {
323			d.Plans = []*Plan{}
324		}
325		// 无备件字段的有效旧库直接使用：缺省视为没有任何备件领用记录，
326		// 领用编号计数器从 1 开始。
327		if d.Parts == nil {
328			d.Parts = []*PartWithdrawal{}
329		}
330		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
331			d.NextPartSeq = 1
332		}
333		// 无附件字段的有效旧库直接使用：缺省视为没有任何附件索引记录，
334		// 附件编号计数器从 1 开始。
335		if d.Attachments == nil {
336			d.Attachments = []*Attachment{}
337		}
338		if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
339			d.NextAttachSeq = 1
340		}
341		if err := validateData(&d); err != nil {
342			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
343		}
344		return &store{dir: dir, data: &d, now: time.Now}, nil
345	}
346	
347	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
348	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
349	func parseTicketSeq(id string) (int, bool) {
350		if !strings.HasPrefix(id, "T") {
351			return 0, false
352		}
353		n, err := strconv.Atoi(id[1:])
354		if err != nil || n < 1 {
355			return 0, false
356		}
357		if fmt.Sprintf("T%04d", n) != id {
358			return 0, false
359		}
360		return n, true
361	}
362	
363	// parsePartSeq 解析 P 加补零正整数序号形式的领用编号，返回序号。
364	// 编号必须与 fmt.Sprintf("P%04d", n)（n ≥ 1）完全一致，否则视为非法。
365	func parsePartSeq(id string) (int, bool) {
366		if !strings.HasPrefix(id, "P") {
367			return 0, false
368		}
369		n, err := strconv.Atoi(id[1:])
370		if err != nil || n < 1 {
371			return 0, false
372		}
373		if fmt.Sprintf("P%04d", n) != id {
374			return 0, false
375		}
376		return n, true
377	}
378	
379	// parseAttachSeq 解析 A 加补零正整数序号形式的附件编号，返回序号。
380	// 编号必须与 fmt.Sprintf("A%04d", n)（n ≥ 1）完全一致，否则视为非法。
381	func parseAttachSeq(id string) (int, bool) {
382		if !strings.HasPrefix(id, "A") {
383			return 0, false
384		}
385		n, err := strconv.Atoi(id[1:])
386		if err != nil || n < 1 {
387			return 0, false
388		}
389		if fmt.Sprintf("A%04d", n) != id {
390			return 0, false
391		}
392		return n, true
393	}
394	
395	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
396	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
397	// 不做任何修复：不补字段、不重编号、不删除记录。
398	func validateData(d *storeData) error {
399		if d.Version != storeVersion {
400			return fmt.Errorf("不支持的数据版本 %d", d.Version)
401		}
402		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil || d.Plans == nil || d.Parts == nil || d.Attachments == nil {
403			return errors.New("缺少必要的数据段")
404		}
405		assets := map[string]*Asset{}
406		for _, a := range d.Assets {
407			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
408				return errors.New("数据矛盾：存在字段不完整的资产记录")
409			}
410			if a.Status != statusAvailable && a.Status != statusRepairing && a.Status != statusDeactivated {
411				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
412			}
413			if assets[a.ID] != nil {
414				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
415			}
416			assets[a.ID] = a
417		}
418		tickets := map[string]*Ticket{}
419		maxTicketSeq := 0
420		for _, t := range d.Tickets {
421			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
422				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
423			}
424			n, ok := parseTicketSeq(t.ID)
425			if !ok {
426				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
427			}
428			if n > maxTicketSeq {
429				maxTicketSeq = n
430			}
431			if t.Status != ticketOpen && t.Status != ticketPending && t.Status != ticketClosed && t.Status != ticketCancelled {
432				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
433			}
434			if assets[t.AssetID] == nil {
435				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
436			}
437			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
438				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
439			}
440			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
441				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
442			}
443			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
444				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
445			}
446			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
447				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
448			}
449			if t.Assignee == "" {
450				if t.AssignedAt != "" || t.AssignNote != "" {
451					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
452				}
453			} else if t.AssignedAt == "" || t.AssignNote == "" {
454				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
455			}
456			if tickets[t.ID] != nil {
457				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
458			}
459			tickets[t.ID] = t
460		}
461		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
462		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
463			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
464				d.NextTicketSeq, maxTicketSeq)
465		}
466		// 备件领用记录：编号唯一且为 P 加补零正整数序号，归属存在的工单且资产归属
467		// 与工单一致，数量为正，累计退回在 [0, 原数量] 内；与履历的接续在下方按
468		// 履历序号重放时核对。
469		parts := map[string]*PartWithdrawal{}
470		maxPartSeq := 0
471		for _, p := range d.Parts {
472			if p == nil || p.ID == "" || p.TicketID == "" || p.AssetID == "" || p.PartID == "" || p.Note == "" {
473				return errors.New("数据矛盾：存在字段不完整的备件领用记录")
474			}
475			n, ok := parsePartSeq(p.ID)
476			if !ok {
477				return fmt.Errorf("计数器矛盾：领用编号 %q 不是 P 加补零正整数序号的形式", p.ID)
478			}
479			if n > maxPartSeq {
480				maxPartSeq = n
481			}
482			if p.Quantity < 1 {
483				return fmt.Errorf("数据矛盾：领用记录 %s 的数量 %d 不是正整数", p.ID, p.Quantity)
484			}
485			if p.Returned < 0 || p.Returned > p.Quantity {
486				return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回 %d 超出原数量 %d", p.ID, p.Returned, p.Quantity)
487			}
488			t := tickets[p.TicketID]
489			if t == nil {
490				return fmt.Errorf("数据矛盾：领用记录 %s 引用了不存在的工单 %s", p.ID, p.TicketID)
491			}
492			if t.AssetID != p.AssetID {
493				return fmt.Errorf("数据矛盾：领用记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
494					p.ID, p.AssetID, t.ID, t.AssetID)
495			}
496			if parts[p.ID] != nil {
497				return fmt.Errorf("数据矛盾：领用编号 %s 重复", p.ID)
498			}
499			parts[p.ID] = p
500		}
501		// 下一领用序号必须为正并大于全部已用序号（允许有间隔）。
502		if d.NextPartSeq < 1 || d.NextPartSeq <= maxPartSeq {
503			return fmt.Errorf("计数器矛盾：下一领用序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
504				d.NextPartSeq, maxPartSeq)
505		}
506		// 附件索引记录：编号唯一且为 A 加补零正整数序号，归属存在的工单且资产归属
507		// 与工单一致，路径为绝对路径，说明非空；撤销状态与理由相互呼应。文件当前
508		// 是否可用不参与整库一致性校验；与履历的接续在下方按履历序号重放时核对。
509		attachments := map[string]*Attachment{}
510		maxAttachSeq := 0
511		for _, a := range d.Attachments {
512			if a == nil || a.ID == "" || a.TicketID == "" || a.AssetID == "" || a.Path == "" || a.Note == "" {
513				return errors.New("数据矛盾：存在字段不完整的附件记录")
514			}
515			n, ok := parseAttachSeq(a.ID)
516			if !ok {
517				return fmt.Errorf("计数器矛盾：附件编号 %q 不是 A 加补零正整数序号的形式", a.ID)
518			}
519			if n > maxAttachSeq {
520				maxAttachSeq = n
521			}
522			if !filepath.IsAbs(a.Path) {
523				return fmt.Errorf("数据矛盾：附件记录 %s 的路径 %q 不是绝对路径", a.ID, a.Path)
524			}
525			t := tickets[a.TicketID]
526			if t == nil {
527				return fmt.Errorf("数据矛盾：附件记录 %s 引用了不存在的工单 %s", a.ID, a.TicketID)
528			}
529			if t.AssetID != a.AssetID {
530				return fmt.Errorf("数据矛盾：附件记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
531					a.ID, a.AssetID, t.ID, t.AssetID)
532			}
533			if a.Revoked && a.RevokeReason == "" {
534				return fmt.Errorf("状态矛盾：已撤销附件 %s 缺少撤销理由", a.ID)
535			}
536			if !a.Revoked && a.RevokeReason != "" {
537				return fmt.Errorf("状态矛盾：有效附件 %s 不应带有撤销理由", a.ID)
538			}
539			if attachments[a.ID] != nil {
540				return fmt.Errorf("数据矛盾：附件编号 %s 重复", a.ID)
541			}
542			attachments[a.ID] = a
543		}
544		// 下一附件序号必须为正并大于全部已用序号（允许有间隔）。
545		if d.NextAttachSeq < 1 || d.NextAttachSeq <= maxAttachSeq {
546			return fmt.Errorf("计数器矛盾：下一附件序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
547				d.NextAttachSeq, maxAttachSeq)
548		}
549		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
550		boundReq := map[string]bool{}
551		boundTicket := map[string]bool{}
552		for _, r := range d.Requests {
553			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
554				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
555			}
556			if boundReq[r.RequestID] {
557				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
558			}
559			boundReq[r.RequestID] = true
560			t := tickets[r.TicketID]
561			if t == nil {
562				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
563			}
564			if t.RequestID != r.RequestID {
565				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
566					r.TicketID, t.RequestID, r.RequestID)
567			}
568			if r.AssetID != t.AssetID || r.Description != t.Description {
569				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
570					r.RequestID, t.ID)
571			}
572			boundTicket[r.TicketID] = true
573		}
574		for _, t := range d.Tickets {
575			if !boundTicket[t.ID] {
576				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
577			}
578		}
579		// 状态：每项资产最多一张未终结工单（未关闭或待验收），有则必须为“维修中”；
580		// 无未终结工单时资产可为“可用”或“停用”，停用与否由停用、恢复使用履历链
581		// 决定，在下方按履历序号重放时核对。
582		openCount := map[string]int{}
583		for _, t := range d.Tickets {
584			if t.Status == ticketOpen || t.Status == ticketPending {
585				openCount[t.AssetID]++
586			}
587		}
588		for _, a := range d.Assets {
589			c := openCount[a.ID]
590			if c > 1 {
591				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未终结工单，最多允许一张", a.ID, c)
592			}
593			if c == 1 {
594				if a.Status != statusRepairing {
595					return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未终结工单，状态应为 %s，实际为 %s",
596						a.ID, c, statusRepairing, a.Status)
597				}
598				continue
599			}
600			if a.Status != statusAvailable && a.Status != statusDeactivated {
601				return fmt.Errorf("状态矛盾：资产 %s 没有未关闭工单，状态应为 %s 或 %s，实际为 %s",
602					a.ID, statusAvailable, statusDeactivated, a.Status)
603			}
604		}
605		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
606		seenSeq := map[int]bool{}
607		reportSeq := map[string]int{}
608		closeSeq := map[string]int{}
609		cancelSeq := map[string]int{}
610		reportCount := map[string]int{}
611		closeCount := map[string]int{}
612		cancelCount := map[string]int{}
613		for i := range d.Events {
614			e := &d.Events[i]
615			if e.Seq < 1 {
616				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
617			}
618			if seenSeq[e.Seq] {
619				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
620			}
621			seenSeq[e.Seq] = true
622			if e.AssetID == "" || e.Kind == "" || e.Content == "" {
623				return errors.New("履历矛盾：存在字段不完整的履历记录")
624			}
625			if e.Kind == eventPlanCreate || e.Kind == eventPlanDone || e.Kind == eventPlanRevoke || e.Kind == eventPlanAdjust {
626				// 保养履历：不属于任何工单，不携带派工、备件或附件字段；日期与间隔在此
627				// 核对，建立、完成、撤销与调整链的接续在下方按序号重放时核对。
628				if e.TicketID != "" || e.From != "" || e.To != "" {
629					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号或派工人员字段", e.Seq, e.Kind)
630				}
631				if e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
632					e.AttachmentID != "" || e.Path != "" {
633					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件或附件字段", e.Seq, e.Kind)
634				}
635				if e.Kind != eventPlanAdjust &&
636					(e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "") {
637					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有方案调整字段", e.Seq, e.Kind)
638				}
639				if e.Kind == eventPlanAdjust {
640					// 调整履历：内容即调整理由（非空已检查）；Due/Interval 为新方案的
641					// 首次到期日与间隔天数，另携带原方案与调整前的下一到期日。
642					if e.Done != "" || e.TargetSeq != 0 {
643						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录不应带有完成日或目标完成履历序号", e.Seq)
644					}
645					if e.NewContent == "" {
646						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录缺少新保养内容", e.Seq)
647					}
648					if _, err := parseDate(e.Due); err != nil {
649						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录新首次到期日无效", e.Seq)
650					}
651					if e.Interval < 1 {
652						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录新间隔天数须为正整数", e.Seq)
653					}
654					if e.OldContent == "" {
655						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录缺少原保养内容", e.Seq)
656					}
657					if _, err := parseDate(e.OldDue); err != nil {
658						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原首次到期日无效", e.Seq)
659					}
660					if e.OldInterval < 1 {
661						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原间隔天数须为正整数", e.Seq)
662					}
663					if _, err := parseDate(e.OldNextDue); err != nil {
664						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原下一到期日无效", e.Seq)
665					}
666					continue
667				}
668				if e.Kind == eventPlanRevoke {
669					// 撤销履历：内容即撤销理由（非空已检查），仅携带目标完成履历序号。
670					if e.Due != "" || e.Done != "" || e.Interval != 0 {
671						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录不应带有到期日、完成日或间隔天数", e.Seq)
672					}
673					if e.TargetSeq < 1 {
674						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录目标完成履历序号须为正整数", e.Seq)
675					}
676					continue
677				}
678				if e.TargetSeq != 0 {
679					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有目标完成履历序号", e.Seq, e.Kind)
680				}
681				due, err := parseDate(e.Due)
682				if err != nil {
683					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录到期日无效", e.Seq, e.Kind)
684				}
685				if e.Kind == eventPlanCreate {
686					if e.Done != "" {
687						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录不应带有完成日", e.Seq)
688					}
689					if e.Interval < 1 {
690						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录间隔天数须为正整数", e.Seq)
691					}
692				} else {
693					if e.Interval != 0 {
694						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录不应带有间隔天数", e.Seq)
695					}
696					done, err := parseDate(e.Done)
697					if err != nil {
698						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录完成日无效", e.Seq)
699					}
700					if done < due {
701						return fmt.Errorf("履历矛盾：履历序号 %d 的完成日早于周期到期日", e.Seq)
702					}
703				}
704				continue
705			}
706			if e.Kind == eventDeactivate || e.Kind == eventReactivate {
707				// 停用/恢复使用为资产级履历：不属于任何工单，From/To 为原状态与新
708				// 状态，不携带派工、保养、备件或附件字段。转换是否接续（可用->停用、
709				// 停用->可用）在下方按履历序号重放时核对。
710				if e.TicketID != "" {
711					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号", e.Seq, e.Kind)
712				}
713				if e.From == "" || e.To == "" {
714					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少原状态或新状态", e.Seq, e.Kind)
715				}
716				if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 ||
717					e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "" ||
718					e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
719					e.AttachmentID != "" || e.Path != "" {
720					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有保养、备件或附件字段", e.Seq, e.Kind)
721				}
722				if assets[e.AssetID] == nil {
723					return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产", e.Seq)
724				}
725				continue
726			}
727			if e.Kind == eventRelocate {
728				// 位置变更为资产级履历：不属于任何工单，From/To 为原位置与新位置，
729				// 新位置非空且与原位置不同，不携带派工、保养、备件或附件字段。
730				// 位置链接续（原位置须等于当时位置）与最终位置一致性在下方按履历
731				// 序号重放时核对。
732				if e.TicketID != "" {
733					return fmt.Errorf("履历矛盾：履历序号 %d 的位置变更记录不应带有工单编号", e.Seq)
734				}
735				if e.From == "" || e.To == "" {
736					return fmt.Errorf("履历矛盾：履历序号 %d 的位置变更记录缺少原位置或新位置", e.Seq)
737				}
738				if e.From == e.To {
739					return fmt.Errorf("履历矛盾：履历序号 %d 的位置变更记录新位置与原位置相同", e.Seq)
740				}
741				if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 ||
742					e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "" ||
743					e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
744					e.AttachmentID != "" || e.Path != "" {
745					return fmt.Errorf("履历矛盾：履历序号 %d 的位置变更记录不应带有保养、备件或附件字段", e.Seq)
746				}
747				if assets[e.AssetID] == nil {
748					return fmt.Errorf("位置矛盾：履历序号 %d 的位置变更记录引用了不存在的资产", e.Seq)
749				}
750				continue
751			}
752			if e.TicketID == "" {
753				return errors.New("履历矛盾：存在字段不完整的履历记录")
754			}
755			if e.Due != "" || e.Done != "" || e.Interval != 0 ||
756				e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "" {
757				return fmt.Errorf("履历矛盾：履历序号 %d 的维修履历不应带有保养字段", e.Seq)
758			}
759			// 目标提交序号与验收决定仅验收履历携带；提交履历的内容即维修结果（非空
760			// 已检查），验收履历的内容即验收意见（非空已检查）。
761			if e.Kind != eventAccept && (e.TargetSeq != 0 || e.Decision != "") {
762				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有目标提交序号或验收决定", e.Seq, e.Kind)
763			}
764			if e.Kind == eventAccept {
765				if e.Decision != decisionApprove && e.Decision != decisionReject {
766					return fmt.Errorf("履历矛盾：履历序号 %d 的验收记录决定无效 %q", e.Seq, e.Decision)
767				}
768				if e.TargetSeq < 1 {
769					return fmt.Errorf("履历矛盾：履历序号 %d 的验收记录目标提交序号须为正整数", e.Seq)
770				}
771			}
772			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
773				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
774			}
775			if e.Kind == eventAssign {
776				if e.To == "" {
777					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
778				}
779				if e.From == e.To {
780					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
781				}
782			}
783			// 附件字段仅附件履历携带；附件履历不携带备件字段。
784			if e.Kind != eventAttach && e.Kind != eventAttachRevoke && (e.AttachmentID != "" || e.Path != "") {
785				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有附件编号或路径", e.Seq, e.Kind)
786			}
787			if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) &&
788				(e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "") {
789				return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件字段", e.Seq, e.Kind)
790			}
791			t := tickets[e.TicketID]
792			if t == nil || assets[e.AssetID] == nil {
793				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
794			}
795			if e.AssetID != t.AssetID {
796				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
797					e.Seq, e.AssetID, t.ID, t.AssetID)
798			}
799			switch e.Kind {
800			case eventReport:
801				if e.Content != t.Description {
802					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
803				}
804				reportCount[t.ID]++
805				reportSeq[t.ID] = e.Seq
806			case eventClose:
807				if e.Content != t.Result {
808					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
809				}
810				closeCount[t.ID]++
811				closeSeq[t.ID] = e.Seq
812			case eventCancel:
813				if e.Content != t.CancelReason {
814					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
815				}
816				cancelCount[t.ID]++
817				cancelSeq[t.ID] = e.Seq
818			case eventAssign:
819				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
820				// 在下方按序号重放时核对。
821			case eventSubmit:
822				// 内容即提交的维修结果（非空已检查）；提交转换（未关闭 -> 待验收）
823				// 在下方按序号重放时核对。
824			case eventAccept:
825				// 内容即验收意见（非空已检查），决定与目标提交序号已在上方核对；
826				// 仅当前待验收提交可处理的接续规则在下方按序号重放时核对。
827			case eventPartWithdraw, eventPartReturn:
828				// 内容即领用说明或退回理由（非空已检查）；备件字段在此核对，
829				// 与领用记录的接续及累计退回在下方按序号重放时核对。
830				if e.PartID == "" || e.WithdrawalID == "" {
831					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少备件编号或领用编号", e.Seq, e.Kind)
832				}
833				if e.Quantity < 1 {
834					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录数量 %d 不是正整数", e.Seq, e.Kind, e.Quantity)
835				}
836				if _, ok := parsePartSeq(e.WithdrawalID); !ok {
837					return fmt.Errorf("履历矛盾：履历序号 %d 的领用编号 %q 不是 P 加补零正整数序号的形式",
838						e.Seq, e.WithdrawalID)
839				}
840			case eventAttach, eventAttachRevoke:
841				// 内容即附件说明或撤销理由（非空已检查）；附件字段在此核对，
842				// 与附件记录的接续及登记、撤销顺序在下方按序号重放时核对。
843				if e.AttachmentID == "" || e.Path == "" {
844					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少附件编号或路径", e.Seq, e.Kind)
845				}
846				if _, ok := parseAttachSeq(e.AttachmentID); !ok {
847					return fmt.Errorf("履历矛盾：履历序号 %d 的附件编号 %q 不是 A 加补零正整数序号的形式",
848						e.Seq, e.AttachmentID)
849				}
850				if !filepath.IsAbs(e.Path) {
851					return fmt.Errorf("履历矛盾：履历序号 %d 的附件路径 %q 不是绝对路径", e.Seq, e.Path)
852				}
853			default:
854				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
855			}
856		}
857		for _, t := range d.Tickets {
858			if reportCount[t.ID] != 1 {
859				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
860			}
861			if t.Status == ticketClosed {
862				if closeCount[t.ID] != 1 {
863					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
864				}
865				if closeSeq[t.ID] <= reportSeq[t.ID] {
866					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
867						t.ID, closeSeq[t.ID], reportSeq[t.ID])
868				}
869			} else if closeCount[t.ID] != 0 {
870				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
871			}
872			if t.Status == ticketCancelled {
873				if cancelCount[t.ID] != 1 {
874					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
875				}
876				if cancelSeq[t.ID] <= reportSeq[t.ID] {
877					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
878						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
879				}
880			} else if cancelCount[t.ID] != 0 {
881				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
882			}
883		}
884		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
885		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
886		sorted := make([]Event, len(d.Events))
887		copy(sorted, d.Events)
888		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
889		// 位置链：每项资产的位置起点为最早一条位置变更履历（按全库序号）的原位置；
890		// 没有位置履历的资产以保存位置为起点。重放时原位置须接续当时位置、新位置
891		// 非空且不同，报修地点取报修履历序号当时的位置。
892		locationOrigin := map[string]string{}
893		relocateExists := map[string]bool{}
894		for _, a := range d.Assets {
895			locationOrigin[a.ID] = a.Location
896		}
897		minRelocateSeq := map[string]int{}
898		for _, e := range d.Events {
899			if e.Kind != eventRelocate {
900				continue
901			}
902			if !relocateExists[e.AssetID] || e.Seq < minRelocateSeq[e.AssetID] {
903				relocateExists[e.AssetID] = true
904				minRelocateSeq[e.AssetID] = e.Seq
905				locationOrigin[e.AssetID] = e.From
906			}
907		}
908		derivedLocation := map[string]string{}
909		for id, origin := range locationOrigin {
910			derivedLocation[id] = origin
911		}
912		ticketReportLocation := map[string]string{}
913		derivedTicket := map[string]string{}
914		derivedOpen := map[string]string{}
915		derivedDeactivated := map[string]bool{}
916		derivedAssignee := map[string]string{}
917		derivedNote := map[string]string{}
918		// 提交验收链（提交、验收、直接关闭、取消的转换、提交身份与目标引用）全部
919		// 由维修链规则核心（repaircore.go）按全库序号重放核对，与日常操作、查询及
920		// replay 回看共用同一套规则；本循环只同步核心推出的工单状态，供派工、备件
921		// 与资产占用等其余接续判定使用。
922		repair := newRepairCore()
923		withdrawSeq := map[string]int{}
924		derivedReturned := map[string]int{}
925		attachRegSeq := map[string]int{}
926		attachRevokeSeq := map[string]int{}
927		for _, e := range sorted {
928			switch e.Kind {
929			case eventReport:
930				if prev := derivedOpen[e.AssetID]; prev != "" {
931					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
932						e.AssetID, prev, e.TicketID)
933				}
934				if derivedDeactivated[e.AssetID] {
935					return fmt.Errorf("履历矛盾：资产 %s 在停用期间产生了工单 %s 的报修",
936						e.AssetID, e.TicketID)
937				}
938				// 报修地点取该报修履历序号当时的资产位置：不能用当前地点、履历
939				// 时间或数组位置代替。
940				ticketReportLocation[e.TicketID] = derivedLocation[e.AssetID]
941				if err := repair.apply(e); err != nil {
942					return repairValidateError(err)
943				}
944				derivedTicket[e.TicketID] = repair.status(e.TicketID)
945				derivedOpen[e.AssetID] = e.TicketID
946			case eventRelocate:
947				// 原位置须接续当时位置；新位置非空且与原位置不同（非空与不同已在
948				// 上方逐条核对）。可用、维修中、停用资产均可变更，不影响工单占用。
949				if e.From != derivedLocation[e.AssetID] {
950					return fmt.Errorf("位置矛盾：资产 %s 的位置变更履历（序号 %d）原位置 %q 与当时位置 %q 不接续",
951						e.AssetID, e.Seq, e.From, derivedLocation[e.AssetID])
952				}
953				derivedLocation[e.AssetID] = e.To
954			case eventDeactivate:
955				// 停用要求当时“可用”（无未关闭工单且未停用）；维修中（有未关闭
956				// 工单）的资产不能停用。From/To 须与实际转换一致。
957				if derivedOpen[e.AssetID] != "" {
958					return fmt.Errorf("履历矛盾：资产 %s 在存在未关闭工单时出现停用履历（序号 %d）",
959						e.AssetID, e.Seq)
960				}
961				if derivedDeactivated[e.AssetID] {
962					return fmt.Errorf("履历矛盾：资产 %s 被重复停用（序号 %d）", e.AssetID, e.Seq)
963				}
964				if e.From != statusAvailable || e.To != statusDeactivated {
965					return fmt.Errorf("履历矛盾：停用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
966						e.Seq, statusAvailable, statusDeactivated, e.From, e.To)
967				}
968				derivedDeactivated[e.AssetID] = true
969			case eventReactivate:
970				// 恢复使用只作用于停用资产；From/To 须与实际转换一致。
971				if !derivedDeactivated[e.AssetID] {
972					return fmt.Errorf("履历矛盾：资产 %s 未停用却出现恢复使用履历（序号 %d）", e.AssetID, e.Seq)
973				}
974				if derivedOpen[e.AssetID] != "" {
975					return fmt.Errorf("履历矛盾：资产 %s 恢复使用（序号 %d）时仍存在未关闭工单",
976						e.AssetID, e.Seq)
977				}
978				if e.From != statusDeactivated || e.To != statusAvailable {
979					return fmt.Errorf("履历矛盾：恢复使用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
980						e.Seq, statusDeactivated, statusAvailable, e.From, e.To)
981				}
982				delete(derivedDeactivated, e.AssetID)
983			case eventAssign:
984				if derivedTicket[e.TicketID] != ticketOpen {
985					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
986				}
987				if e.From != derivedAssignee[e.TicketID] {
988					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
989						e.TicketID, e.Seq, e.From)
990				}
991				derivedAssignee[e.TicketID] = e.To
992				derivedNote[e.TicketID] = e.Content
993			case eventClose:
994				// 关闭的全部接续判定由维修链规则核心完成：未关闭且从未提交可直接
995				// 关闭；验收通过待关闭中间态只接受同单且内容与该次提交结果匹配的
996				// 关闭；待验收、已终结或首次提交后的直接关闭均矛盾。
997				if err := repair.apply(e); err != nil {
998					return repairValidateError(err)
999				}
1000				derivedTicket[e.TicketID] = repair.status(e.TicketID)
1001				delete(derivedOpen, e.AssetID)
1002			case eventCancel:
1003				// 取消的全部接续判定由维修链规则核心完成：未关闭与待验收可取消，
1004				// 已关闭、已取消或验收通过待关闭中间态矛盾；取消清除当前待验收
1005				// 提交但保留全部提交历史。
1006				if err := repair.apply(e); err != nil {
