1265		case ruleAdjustFirstDue:
1266			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）的新首次到期日 %s 未严格晚于未撤销完成（序号 %d）的实际完成日 %s",
1267				re.seq, re.dateA, re.doneSeq, re.dateB)
1268		case ruleRevokeOldSegment:
