1294	// repairValidateError 把维修链规则核心返回的规则冲突包装为台账校验场景的错误
1295	// （指明“履历矛盾”类别）；调用方拒绝查询与写入并保留原文件，不自动修复。
1296	func repairValidateError(err error) error {
1297		var re *repairRuleError
1298		if !errors.As(err, &re) {
1299			return err
1300		}
1301		switch re.code {
1302		case ruleRepairDuplicateReport:
1303			return fmt.Errorf("履历矛盾：工单 %s 被重复报修", re.ticketID)
1304		case ruleSubmitNotOpen:
1305			return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现提交履历（序号 %d）",
1306				re.ticketID, re.seq)
1307		case ruleSubmitEmptyResult:
1308			return fmt.Errorf("履历矛盾：提交履历（序号 %d）的维修结果为空", re.seq)
1309		case ruleCloseNoReport:
1310			return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现关闭履历（序号 %d）", re.ticketID, re.seq)
1311		case ruleCloseAlreadyClosed:
1312			return fmt.Errorf("履历矛盾：工单 %s 已关闭后又出现关闭履历（序号 %d）", re.ticketID, re.seq)
1313		case ruleCloseAlreadyCancelled:
1314			return fmt.Errorf("履历矛盾：工单 %s 已取消后出现关闭履历（序号 %d）", re.ticketID, re.seq)
1315		case ruleClosePending:
1316			return fmt.Errorf("履历矛盾：工单 %s 处于待验收时出现直接关闭履历（序号 %d），须先验收或取消",
1317				re.ticketID, re.seq)
1318		case ruleCloseAfterSubmit:
1319			return fmt.Errorf("履历矛盾：工单 %s 首次提交后只能验收通过或取消终结，却出现直接关闭履历（序号 %d）",
1320				re.ticketID, re.seq)
1321		case ruleCloseApprovedMismatch:
1322			return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）内容 %q 与验收通过的提交维修结果 %q 不一致",
1323				re.ticketID, re.seq, re.contentA, re.contentB)
1324		case ruleCloseEmptyResult:
1325			return fmt.Errorf("履历矛盾：关闭履历（序号 %d）的维修结果为空", re.seq)
1326		case ruleCancelNoReport:
1327			return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现取消履历（序号 %d）", re.ticketID, re.seq)
1328		case ruleCancelAlreadyClosed:
1329			return fmt.Errorf("履历矛盾：工单 %s 已关闭后出现取消履历（序号 %d）", re.ticketID, re.seq)
1330		case ruleCancelAlreadyCancelled:
1331			return fmt.Errorf("履历矛盾：工单 %s 已取消后又出现取消履历（序号 %d）", re.ticketID, re.seq)
1332		case ruleCancelApprovedPending:
1333			return fmt.Errorf("履历矛盾：工单 %s 在验收通过待关闭时出现取消履历（序号 %d），验收与关闭须同次保存",
1334				re.ticketID, re.seq)
1335		case ruleAcceptNotPending:
1336			return fmt.Errorf("履历矛盾：工单 %s 在未处于待验收状态时出现验收履历（序号 %d）",
1337				re.ticketID, re.seq)
1338		case ruleAcceptEmptyComment:
1339			return fmt.Errorf("履历矛盾：验收履历（序号 %d）的验收意见为空", re.seq)
1340		case ruleAcceptBadDecision:
1341			return fmt.Errorf("履历矛盾：验收履历（序号 %d）的决定无效", re.seq)
1342		case ruleAcceptTargetUnknown:
1343			return fmt.Errorf("履历矛盾：验收履历（序号 %d）的目标提交序号 %d 不存在",
1344				re.seq, re.target)
1345		case ruleAcceptTargetNotSubmit:
1346			return fmt.Errorf("履历矛盾：验收履历（序号 %d）的目标序号 %d 不是提交履历（实际为%s履历）",
1347				re.seq, re.target, re.kind)
1348		case ruleAcceptTargetCrossTicket:
1349			return fmt.Errorf("履历矛盾：验收履历（序号 %d）的目标提交序号 %d 属于工单 %s，不能用于工单 %s",
1350				re.seq, re.target, re.owner, re.ticketID)
1351		case ruleAcceptTargetProcessed:
1352			return fmt.Errorf("履历矛盾：验收履历（序号 %d）的目标提交序号 %d 已处理或不是工单 %s 当前待验收提交",
1353				re.seq, re.target, re.ticketID)
1354		}
1355		return err
1356	}
1357	
1358	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
1359	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
1360	// 保持不变，不留下部分业务变化。
1361	func (s *store) save() error {
1362		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
1363		for i, e := range s.data.Events {
1364			s.data.EventsJSON[i] = e.toJSON()
1365		}
1366		if err := validateData(s.data); err != nil {
1367			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
1368		}
1369		var buf bytes.Buffer
1370		enc := json.NewEncoder(&buf)
1371		enc.SetIndent("", "  ")
1372		if err := enc.Encode(s.data); err != nil {
1373			return fmt.Errorf("编码数据失败: %w", err)
1374		}
1375		if err := os.MkdirAll(s.dir, 0o755); err != nil {
1376			return fmt.Errorf("创建数据目录失败: %w", err)
1377		}
1378		path := filepath.Join(s.dir, dataFileName)
1379		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
1380		if err != nil {
1381			return fmt.Errorf("创建临时数据文件失败: %w", err)
1382		}
1383		tmpName := tmp.Name()
1384		abort := func(err error) error {
1385			_ = tmp.Close()
1386			_ = os.Remove(tmpName)
1387			return err
1388		}
1389		if _, err := tmp.Write(buf.Bytes()); err != nil {
1390			abort(nil)
1391			return fmt.Errorf("写入数据失败: %w", err)
1392		}
1393		if err := tmp.Sync(); err != nil {
1394			abort(nil)
1395			return fmt.Errorf("写入数据失败: %w", err)
1396		}
1397		if err := tmp.Close(); err != nil {
1398			_ = os.Remove(tmpName)
1399			return fmt.Errorf("写入数据失败: %w", err)
1400		}
1401		if err := os.Rename(tmpName, path); err != nil {
1402			_ = os.Remove(tmpName)
1403			return fmt.Errorf("保存数据失败: %w", err)
1404		}
1405		return nil
1406	}
1407	
1408	func (s *store) findAsset(id string) *Asset {
1409		for _, a := range s.data.Assets {
1410			if a.ID == id {
1411				return a
1412			}
1413		}
1414		return nil
1415	}
1416	
1417	func (s *store) findTicket(id string) *Ticket {
1418		for _, t := range s.data.Tickets {
1419			if t.ID == id {
1420				return t
1421			}
1422		}
1423		return nil
1424	}
1425	
1426	func (s *store) findRequest(requestID string) *requestBinding {
1427		for i := range s.data.Requests {
1428			if s.data.Requests[i].RequestID == requestID {
1429				return &s.data.Requests[i]
1430			}
1431		}
1432		return nil
1433	}
1434	
1435	// openTicketOf 返回资产当前未终结（未关闭或待验收）的工单；待验收工单仍占用
1436	// 资产，因此报修、停用、恢复使用与详情展示都把待验收视为未终结。
1437	func (s *store) openTicketOf(assetID string) *Ticket {
1438		for _, t := range s.data.Tickets {
1439			if t.AssetID == assetID && (t.Status == ticketOpen || t.Status == ticketPending) {
1440				return t
1441			}
1442		}
1443		return nil
1444	}
1445	
1446	func (s *store) eventsOf(assetID string) []Event {
1447		out := make([]Event, 0)
1448		for _, e := range s.data.Events {
1449			if e.AssetID == assetID {
1450				out = append(out, e)
1451			}
1452		}
1453		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
1454		return out
1455	}
1456	
1457	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
1458	func (s *store) nextEventSeq() (int, error) {
1459		maxSeq := 0
1460		for _, e := range s.data.Events {
1461			if e.Seq > maxSeq {
1462				maxSeq = e.Seq
1463			}
1464		}
1465		if maxSeq == math.MaxInt {
1466			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
1467		}
1468		return maxSeq + 1, nil
1469	}
1470	
1471	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
1472	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
1473	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
1474		s.data.Events = append(s.data.Events, Event{
1475			Seq:      seq,
1476			AssetID:  assetID,
1477			TicketID: ticketID,
1478			Kind:     kind,
1479			Content:  content,
1480			From:     from,
1481			To:       to,
1482			Time:     s.now(),
1483		})
1484	}
1485	
1486	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
1487		if s.findAsset(id) != nil {
1488			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
1489		}
1490		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
1491		s.data.Assets = append(s.data.Assets, a)
1492		return a, nil
1493	}
1494	
1495	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
1496	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
1497	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
1498		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
1499		// 资产或描述不同 => 拒绝。
1500		if r := s.findRequest(requestID); r != nil {
1501			if r.AssetID != assetID || r.Description != description {
1502				return nil, false, fmt.Errorf(
1503					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
1504					errConflict, requestID, r.AssetID)
1505			}
1506			t := s.findTicket(r.TicketID)
1507			if t == nil {
1508				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
1509			}
1510			return t, true, nil
1511		}
1512	
1513		asset := s.findAsset(assetID)
1514		if asset == nil {
1515			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
1516		}
1517		if asset.Status == statusDeactivated {
1518			// 停用期间拒绝新报修，也不绑定新请求标识；恢复使用后可用同一标识重试。
1519			return nil, false, fmt.Errorf("%w: 资产 %s 已停用，不能报修", errConflict, assetID)
1520		}
1521		if t := s.openTicketOf(assetID); t != nil {
1522			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
1523		}
1524		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
1525		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
1526		seq := s.data.NextTicketSeq
1527		if seq < 1 || seq == math.MaxInt {
1528			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
1529		}
1530		eventSeq, err := s.nextEventSeq()
1531		if err != nil {
1532			return nil, false, err
1533		}
1534		t := &Ticket{
1535			ID:          fmt.Sprintf("T%04d", seq),
1536			AssetID:     assetID,
1537			Description: description,
1538			RequestID:   requestID,
1539			Status:      ticketOpen,
1540			CreatedAt:   s.now().Format(time.RFC3339),
1541			// 报修地点在报修时按当时资产位置确定；之后位置变更不改写本字段，
1542			// 由加载/保存校验保证它与按报修履历序号追溯的位置一致。
1543			ReportLocation: asset.Location,
1544		}
1545		s.data.NextTicketSeq = seq + 1
1546		s.data.Tickets = append(s.data.Tickets, t)
1547		s.data.Requests = append(s.data.Requests, requestBinding{
1548			RequestID:   requestID,
1549			AssetID:     assetID,
1550			Description: description,
1551			TicketID:    t.ID,
1552		})
1553		asset.Status = statusRepairing
1554		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
1555		return t, false, nil
1556	}
1557	
1558	// closeTicket 关闭未关闭工单并把资产恢复为可用。仅从未提交的工单可直接关闭；
1559	// 首次提交后只能验收通过或取消终结（退回后也不能绕过验收直接关闭）；验收通过
1560	// 的关闭履历只由 acceptSubmission 在同一保存中追加。能否关闭的判定（未终结、
1561	// 未提交过、非空结果）由维修链规则核心对候选关闭履历完成。失败路径不修改任何
1562	// 业务数据。
1563	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1564		t := s.findTicket(ticketID)
1565		if t == nil {
1566			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1567		}
1568		if result == "" {
1569			return nil, nil, fmt.Errorf("%w: 维修结果不能为空", errConflict)
1570		}
1571		core, err := s.repairCore()
1572		if err != nil {
1573			return nil, nil, err
1574		}
1575		// 候选履历不带序号：核心只按当时工单状态与内容判定；判定通过后才分配序号。
1576		if err := core.apply(Event{TicketID: ticketID, Kind: eventClose, Content: result}); err != nil {
1577			return nil, nil, repairOpError(err)
1578		}
1579		asset := s.findAsset(t.AssetID)
1580		if asset == nil {
1581			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1582		}
1583		eventSeq, err := s.nextEventSeq()
1584		if err != nil {
1585			return nil, nil, err
1586		}
1587		t.Status = ticketClosed
1588		t.Result = result
1589		t.ClosedAt = s.now().Format(time.RFC3339)
1590		asset.Status = statusAvailable
1591		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1592		return t, asset, nil
1593	}
1594	
1595	// cancelTicket 取消未关闭或待验收工单并把资产恢复为可用。取消是终态，但不代表
1596	// 维修完成：不填写维修结果，不删除工单、履历（含全部提交与验收履历）或请求
1597	// 绑定，工单编号不回退也不复用。能否取消（未关闭或待验收；已关闭、已取消或
1598	// 验收通过待关闭中间态拒绝）由维修链规则核心对候选取消履历完成，取消同时清除
1599	// 当前待验收提交。失败路径不修改任何业务数据。
1600	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1601		t := s.findTicket(ticketID)
1602		if t == nil {
1603			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1604		}
1605		if reason == "" {
1606			return nil, nil, fmt.Errorf("%w: 取消理由不能为空", errConflict)
1607		}
1608		core, err := s.repairCore()
1609		if err != nil {
1610			return nil, nil, err
1611		}
1612		if err := core.apply(Event{TicketID: ticketID, Kind: eventCancel, Content: reason}); err != nil {
1613			return nil, nil, repairOpError(err)
1614		}
1615		asset := s.findAsset(t.AssetID)
1616		if asset == nil {
1617			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1618		}
1619		eventSeq, err := s.nextEventSeq()
1620		if err != nil {
1621			return nil, nil, err
1622		}
1623		t.Status = ticketCancelled
1624		t.CancelReason = reason
1625		t.CancelledAt = s.now().Format(time.RFC3339)
1626		asset.Status = statusAvailable
1627		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1628		return t, asset, nil
1629	}
1630	
1631	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1632	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1633	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1634	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1635	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1636	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1637		t := s.findTicket(ticketID)
1638		if t == nil {
1639			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1640		}
1641		if t.Status == ticketClosed {
1642			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1643		}
1644		if t.Status == ticketCancelled {
1645			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1646		}
1647		if t.Status == ticketPending {
1648			return nil, fmt.Errorf("%w: 工单 %s 处于待验收，不能派工", errConflict, ticketID)
1649		}
1650		if assignee == "" {
1651			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1652		}
1653		if note == "" {
1654			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1655		}
1656		if t.Assignee == assignee {
1657			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1658				errConflict, ticketID, assignee)
1659		}
1660		eventSeq, err := s.nextEventSeq()
1661		if err != nil {
1662			return nil, err
1663		}
1664		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1665		t.Assignee = assignee
1666		t.AssignedAt = s.now().Format(time.RFC3339)
1667		t.AssignNote = note
1668		return t, nil
1669	}
1670

