379		}
380		mustSave(t, s)
381		before := readFileBytes(t, dir)
382	
383		manifest, _ := writeManifest(t, `[
384	  {"asset_id":"EQ-1","description":"卡纸","request_id":"req-old"},
385	  {"asset_id":"EQ-2","description":"异响","request_id":"req-live"}
386	]`)
387		code, out, errOut := runBatch(t, dir, manifest)
388		if code != 0 {
389			t.Fatalf("纯重放应成功: %s", errOut)
390		}
391		if !strings.Contains(out, "req-old\tEQ-1\tT0001\t已关闭\t重放") ||
392			!strings.Contains(out, "req-live\tEQ-2\tT0002\t未关闭\t重放") {
393			t.Fatalf("重放应返回原工单及当前状态，得到:\n%s", out)
394		}
395		if !strings.Contains(out, "未创建工单、未写入任何记录") {
396			t.Fatalf("纯重放应明确提示未写入记录，得到:\n%s", out)
397		}
398		if !bytes.Equal(readFileBytes(t, dir), before) {
399			t.Fatal("纯重放不应改动台账文件")
400		}
401		s2, err := openStore(dir)
402		if err != nil {
403			t.Fatal(err)
404		}
405		if a := s2.findAsset("EQ-1"); a.Status != statusDeactivated {
406			t.Fatalf("重放不应改变资产状态，EQ-1 应为停用，得到 %s", a.Status)
407		}
408		if tk := s2.findTicket("T0001"); tk.Status != ticketClosed {
409			t.Fatalf("重放不应重开原单，T0001 应为已关闭，得到 %s", tk.Status)
410		}
411	}
412	
413	// 保存失败（目录不可写）：整批失败，原文件字节不变，不留下部分记录或请求
414	// 绑定、不消耗编号；恢复写入条件后重载重试成功。
415	func TestBatchReportSaveFailureReloadRetry(t *testing.T) {
416		dir := t.TempDir()
417		s := newStoreAt(t, dir)
418		for _, a := range [][3]string{{"EQ-1", "打印机", "一楼"}, {"EQ-2", "空调", "二楼"}} {
419			if _, err := s.registerAsset(a[0], a[1], a[2]); err != nil {
420				t.Fatal(err)
421			}
422		}
423		mustSave(t, s)
424		before := readFileBytes(t, dir)
425	
426		manifest, _ := writeManifest(t, `[
427	  {"asset_id":"EQ-1","description":"卡纸","request_id":"req-a"},
428	  {"asset_id":"EQ-2","description":"异响","request_id":"req-b"}
429	]`)
430		if err := os.Chmod(dir, 0o555); err != nil {
431			t.Fatal(err)
432		}
433		code, _, _ := runBatch(t, dir, manifest)
434		if err := os.Chmod(dir, 0o755); err != nil {
435			t.Fatal(err)
436		}
437		if code == 0 {
438			t.Skip("当前环境忽略目录写权限，无法模拟写入失败")
439		}
440		if code != 1 {
441			t.Fatalf("写入失败应退出 1，得到 %d", code)
442		}
443		if !bytes.Equal(readFileBytes(t, dir), before) {
444			t.Fatal("写入失败不应改动原文件字节")
445		}
446		// 重载后看不到部分变化：无工单、无绑定，编号未消耗。
447		s2, err := openStore(dir)
448		if err != nil {
449			t.Fatalf("写入失败后应可正常重载: %v", err)
450		}
451		if len(s2.data.Tickets) != 0 || len(s2.data.Requests) != 0 || s2.data.NextTicketSeq != 1 {
452			t.Fatal("写入失败不应留下部分记录或请求绑定、不应消耗编号")
453		}
454		// 恢复条件后重试成功，编号从 1 连续分配。
455		code, out, errOut := runBatch(t, dir, manifest)
456		if code != 0 {
457			t.Fatalf("恢复写入条件后重试应成功: %s", errOut)
458		}
459		if !strings.Contains(out, "req-a\tEQ-1\tT0001") || !strings.Contains(out, "req-b\tEQ-2\tT0002") {
460			t.Fatalf("重试应分配 T0001、T0002，得到:\n%s", out)
461		}
462	}
463	
464	// 清单格式错误（退出码 2）：空清单、格式错误、缺少必填内容、未知字段、
465	// 多余内容均整批拒绝并指出位置；清单文件读取失败为退出码 1。
466	func TestBatchReportManifestFormatErrors(t *testing.T) {
467		cases := []struct {
468			name    string
469			content string
470			want    string
471		}{
472			{"空文件", "", "为空"},
473			{"仅空白", "  \n ", "为空"},
474			{"空数组", "[]", "为空"},
475			{"非法 JSON", "{", "格式错误"},
476			{"非数组", `{"asset_id":"EQ-1"}`, "格式错误"},
477			{"多余内容", "[] {}", "多余内容"},
478			{"未知字段", `[{"asset_id":"EQ-1","description":"卡纸","request_id":"r1","batch_id":"b1"}]`, "格式错误"},
479			{"缺资产编号", `[{"description":"卡纸","request_id":"r1"}]`, "清单第 1 项"},
480			{"空故障描述", `[{"asset_id":"EQ-1","description":"","request_id":"r1"}]`, "清单第 1 项"},
481			{"缺请求标识", `[{"asset_id":"EQ-1","description":"卡纸"}]`, "清单第 1 项"},
482			{"空请求标识", `[{"asset_id":"EQ-1","description":"卡纸","request_id":" "}]`, ""}, // 非空即合法
483			{"第二项缺内容", `[
484	  {"asset_id":"EQ-1","description":"卡纸","request_id":"r1"},
485	  {"asset_id":"EQ-2","request_id":"r2"}
486	]`, "清单第 2 项"},
487			{"空对象项", `[null]`, "清单第 1 项"},
488		}
489		for _, tc := range cases {
490			t.Run(tc.name, func(t *testing.T) {
491				dir := filepath.Join(t.TempDir(), "data")
492				manifest, _ := writeManifest(t, tc.content)
493				code, _, errOut := runBatch(t, dir, manifest)
494				if tc.name == "空请求标识" {
495					// 仅空白字符的请求标识非空，进入业务流程：未知资产（退出码 1）。
496					if code != 1 {
497						t.Fatalf("非空请求标识应进入业务流程，退出码 = %d", code)
498					}
499					return
500				}
501				if code != 2 {
502					t.Fatalf("清单格式错误应退出 2，得到 %d: %s", code, errOut)
503				}
504				if tc.want != "" && !strings.Contains(errOut, tc.want) {
505					t.Fatalf("错误信息应包含 %q，得到: %s", tc.want, errOut)
506				}
507				if _, err := os.Stat(dir); !os.IsNotExist(err) {
508					t.Fatal("清单格式错误不应初始化数据目录")
509				}
510			})
511		}
512	
513		// 清单文件不存在：读取失败，退出码 1。
514		dir := t.TempDir()
515		code, _, errOut := runBatch(t, dir, filepath.Join(dir, "不存在.json"))
516		if code != 1 || !strings.Contains(errOut, "读取报修清单失败") {
517			t.Fatalf("清单读取失败应退出 1 并说明原因，退出码 = %d: %s", code, errOut)
518		}
519		// 缺少 --file 参数：退出码 2。
520		var out, errBuf bytes.Buffer
521		if code := run([]string{"batch-report", "--data-dir", dir}, &out, &errBuf); code != 2 {
522			t.Fatalf("缺少 --file 应退出 2，得到 %d", code)
523		}
524	}
