	// 引用当前段序号（调整履历 3）：同一到期日正常登记。
	manifest, _ := writeManifest(t,
		`[{"asset_id":"EQ-1","due":"2026-01-31","done":"2026-01-31","result":"新段首保","segment_seq":3}]`)
